{
  "legal_owner": {
    "status": "established",
    "names": ["KRZZ Licensing, LLC"],
    "citations": [
      {
        "url": "https://www.fcc.report/LMS/0000173591",
        "quote": "KRZZ | 1092 | FM | KRZZ Licensing, LLC | SAN FRANCISCO, CA"
      },
      {
        "url": "https://fcc.report/LMS/0000300753",
        "quote": "Applicant | KRZZ LICENSING, LLC"
      }
    ]
  },
  "operator": {
    "status": "same_as_owner",
    "names": ["KRZZ Licensing, LLC"],
    "citations": [
      {
        "url": "https://documents.elevenflo.com/uuid_database_8_14_23/479e8e8c-8f1e-4f52-9a77-0ab4eca700d8.pdf",
        "quote": "day-to-day broadcast operations, which shall remain solely with the FCC licensees"
      }
    ]
  },
  "chain": [
    {
      "child": "KRZZ Licensing, LLC",
      "parent": "SBS Bay Area, LLC",
      "relation": "Subsidiary of SBS Bay Area, LLC, as depicted in Exhibit B, Organizational Chart, to the May 11, 2026 court declaration.",
      "citations": [
        {
          "url": "https://documents.elevenflo.com/uuid_database_8_14_23/479e8e8c-8f1e-4f52-9a77-0ab4eca700d8.pdf",
          "quote": "Organizational Chart"
        }
      ]
    },
    {
      "child": "SBS Bay Area, LLC",
      "parent": "Spanish Broadcasting System, Inc.",
      "relation": "Wholly owned subsidiary; the May 11, 2026 organizational chart also places SBS Bay Area directly under Spanish Broadcasting System, Inc.",
      "citations": [
        {
          "url": "https://www.sec.gov/Archives/edgar/data/927720/000095012305003256/y06789e10vk.htm",
          "quote": "SBS Bay Area, LLC, a wholly-owned subsidiary of SBS"
        },
        {
          "url": "https://documents.elevenflo.com/uuid_database_8_14_23/479e8e8c-8f1e-4f52-9a77-0ab4eca700d8.pdf",
          "quote": "Organizational Chart"
        }
      ]
    }
  ],
  "ultimate_parent": {
    "status": "single",
    "names": ["Spanish Broadcasting System, Inc."],
    "citations": [
      {
        "url": "https://docs.fcc.gov/public/attachments/DA-26-933A1.pdf",
        "quote": "the licensee subsidiaries of Spanish Broadcasting System, Inc."
      }
    ]
  },
  "controlling_person": {
    "status": "established",
    "names": ["Raúl Alarcón, Jr."],
    "citations": [
      {
        "url": "https://www.spanishbroadcasting.com/wp-content/uploads/sites/5/2024/02/SBS-Material-Change-Report-020624-RA-President.pdf",
        "quote": "Mr. Alarcón remains the Company’s largest and sole controlling shareholder."
      },
      {
        "url": "https://documents.elevenflo.com/uuid_database_8_14_23/479e8e8c-8f1e-4f52-9a77-0ab4eca700d8.pdf",
        "quote": "Raúl Alarcón Jr. has voting control over all but 350 shares"
      }
    ]
  },
  "leader": {
    "status": "established",
    "name": "Raúl Alarcón",
    "role": "Chief Executive Officer",
    "entity": "Spanish Broadcasting System, Inc.",
    "citations": [
      {
        "url": "https://www.spanishbroadcasting.com/leadership/executive-management/raul-alarcon",
        "quote": "Raúl Alarcón\nCEO, Chairman"
      }
    ]
  },
  "transactions": [
    {
      "description": "SBS entered a restructuring support agreement contemplating cancellation of existing equity and issuance of the reorganized company's equity to noteholders, subject to management-incentive dilution. This was a proposed ownership change, not a completed transfer.",
      "status": "announced",
      "date": "2026-04-08",
      "citations": [
        {
          "url": "https://www.spanishbroadcasting.com/wp-content/uploads/sites/5/2026/04/RSA-Press-Release-Package-RP-List.pdf",
          "quote": "holders of the Notes would receive 100% of the common stock in the reorganized Company"
        }
      ]
    },
    {
      "description": "The bankruptcy court approved the reorganization plan. Court confirmation did not itself complete the FCC-regulated ownership transfer.",
      "status": "approved",
      "date": "2026-07-01",
      "citations": [
        {
          "url": "https://www.radioworld.com/news-and-business/business-and-law/sbs-reorganization-plan-now-waits-on-the-fcc",
          "quote": "The court order approving the reorganization plan was signed July 1 by U.S. Bankruptcy Judge Brendan Shannon."
        }
      ]
    },
    {
      "description": "FCC applications to implement the restructuring were filed July 16, 2026. The FCC established a pleading cycle on September 2, 2026; approval and consummation were not established as of October 4, 2026.",
      "status": "announced",
      "date": "2026-07-16",
      "citations": [
        {
          "url": "https://docs.fcc.gov/public/attachments/DA-26-933A1.pdf",
          "quote": "Opposition Date: October 19, 2026\nReply Date: October 26, 2026"
        }
      ]
    }
  ],
  "uncertainty": "As of October 4, 2026, the evidence supports the existing chain KRZZ Licensing, LLC → SBS Bay Area, LLC → Spanish Broadcasting System, Inc., with Raúl Alarcón, Jr. controlling SBS and remaining its CEO. SBS was undergoing Chapter 11 restructuring; the prospective creditor owners should not be treated as current owners without evidence of FCC approval and consummation. There is a naming inconsistency: the September 2 FCC notice's station appendix says 'KRZZ Licensing, Inc.', whereas the ownership report, July/August 2026 application record, and May 2026 bankruptcy documents identify 'KRZZ Licensing, LLC'. No separate operator was established."
}

